"""Load configuration from files and strings."""

import os

from miniconf.errors import ConfigError
from miniconf.parser import parse_lines

INCLUDE_DIRECTIVE = "@include"


def _read_lines(path):
    with open(path, "r", encoding="utf-8") as fh:
        return fh.read().splitlines()


def _expand(path, lines, stack):
    """Recursively replace ``@include`` lines with the referenced file's lines."""
    base_dir = os.path.dirname(os.path.abspath(path))
    expanded = []
    for raw in lines:
        tokens = raw.split(None, 1)
        if not tokens or tokens[0] != INCLUDE_DIRECTIVE:
            expanded.append(raw)
            continue
        target = tokens[1].strip() if len(tokens) > 1 else ""
        if not target:
            raise ConfigError("{}: @include requires a path".format(path))
        target_path = os.path.join(base_dir, target)
        key = os.path.realpath(target_path)
        if key in stack:
            raise ConfigError(
                "{}: include cycle detected for {}".format(path, target)
            )
        if not os.path.isfile(target_path):
            raise ConfigError(
                "{}: included file not found: {}".format(path, target)
            )
        try:
            child_lines = _read_lines(target_path)
        except OSError as exc:
            raise ConfigError(
                "{}: cannot read included file {}: {}".format(path, target, exc)
            )
        stack.append(key)
        try:
            expanded.extend(_expand(target_path, child_lines, stack))
        finally:
            stack.pop()
    return expanded


def load(path):
    """Read and parse the configuration file at ``path``.

    ``@include <path>`` lines are expanded in place with the contents of the
    referenced file, resolved relative to the including file's directory.
    """
    lines = _read_lines(path)
    lines = _expand(path, lines, [os.path.realpath(path)])
    return parse_lines(lines)


def loads(text):
    """Parse configuration from a string."""
    return parse_lines(text.splitlines())
